import random

from abc import ABC
from typing import List, Union, Optional

from taf.rfrl.csv4all.resources.node.exceptions import VerificationBtsFailed
from taf.rfrl.csv4all.resources.test_cases.csv4all_test import CSV4AllTest
from taf.rfrl.csv4all.resources.utilities.decorators import method_decorator
from taf.rfrl.csv4all.resources.utilities.exceptions import FatalError
from taf.rfrl.csv4all.resources.utilities.utilities import test_logger, wait_until_success


class DeltaCommissioningTest(CSV4AllTest, ABC):

    def __init__(self, nodes_details: List[dict], test_nodes_details: List[dict], iterations_per_node: int,
                 report: bool, delta: str, rat_to_reset: str = None, calculate_kpi: Optional[bool] = True,
                 kpi_targets: Optional[dict] = None, use_dcap: Optional[bool] = False,
                 qc_domain: Optional[str] = None, qc_id: Optional[str] = None, qc_project: Optional[str] = None,
                 customers_list: Union[str, list] = None, report_comment: Optional[str] = None,
                 sw_build: Optional[str] = None, topology: Optional[str] = None,
                 stop_test_after_fail: bool = False, l3_call_method: Optional[callable] = None,
                 detailed_console_log: bool = True, collect_passed_logs: int = 0):
        super().__init__(nodes_details, test_nodes_details, iterations_per_node, report,
                         calculate_kpi, kpi_targets, use_dcap, qc_domain, qc_id, qc_project, customers_list,
                         report_comment, sw_build, topology, stop_test_after_fail, l3_call_method,
                         detailed_console_log, collect_passed_logs)
        self.delta = delta
        self.rat_to_reset = rat_to_reset

    def test_operation(self, node):
        if self.rat_to_reset and not self.delta:
            raise FatalError("Default delta for RAT reset is not supported yet")
        delta = self._generate_delta_scf_from_template(node, self.delta) if self.delta else self.set_delta(node)
        if self.rat_to_reset == "LTE":
            lte_cells = [cell for cell in node.cells_per_rat['lte'].keys()]
            self.add_allowed_dss_faults_as_test_specific(lte_cells)
        node.perform_delta_recommissioning(delta, skip_parameter_relation_errors=True)
        if self.rat_to_reset:
            self.wait_till_rat_is_reseted(node, self.rat_to_reset)
            self.set_l3_all_dependent_cells(node, self.rat_to_reset)
            self.check_cells_not_affected(node)

    def run_iteration_postcondition(self, node):
        self.restore_base_scf(node)

    @method_decorator()
    def set_delta(self, node) -> str:
        node.admin.create_delta("delta")
        if self.reset_incrementation:
            parameter = "actEAPMode"
            distname = f"{node.mrbts_id}/MNL-1/MNLENT-1/FEATCADM-1"
            acteapmode_values = ["EAP disabled", "Authenticator initiated mode",
                                 "Combined Authenticator initiated mode and Supplicant initiated mode"]
            current_acteap_value = node.scf.get_value_from_scf(dist_name=distname, p_name=parameter)
            acteapmode_values.remove(current_acteap_value)
            node.admin.append_parameter_update_to_delta(dist_name=distname, parameter=parameter,
                                                        value=random.choice(acteapmode_values), delta_id="delta")
        else:
            parameter = "btsName"
            btsname = node.scf.get_value_from_scf(dist_name=node.mrbts_id, p_name=parameter)
            node.admin.append_parameter_update_to_delta(dist_name=node.mrbts_id, parameter=parameter,
                                                        value=f"[CSV4ALL]_{btsname}", delta_id="delta")

        test_logger(f"Delta was not provided. Test will be executed with changing {parameter} parameter on "
                    f"{node.node_alias}", "warn")
        node.admin.save_delta(target_file_name=f"{self.log_dir}/{node.node_alias}/delta.json", delta_id="delta")
        return node.admin.get_delta("delta")

    @staticmethod
    def __delta_argument_deprecated(delta):
        if delta:
            test_logger(f"Argument delta is deprecated, please define delta under nodes", "WARN")

    @staticmethod
    @method_decorator()
    def verify_if_rat_is_reseted(node, rat: str):
        node.btsverify.set_current_bts_info()
        cells_status = node.btsverify.cells_verifier.verify_rat_cells_state(rat)
        cells_reseted = [cell for entity in cells_status for cell, states in entity.items()
                         if any("Error" in state_value for state_value in states.values())]
        if not cells_reseted:
            raise Exception(f"RAT: {rat} is not reseted")

    @method_decorator()
    def wait_till_rat_is_reseted(self, node, rat: str):
        test_logger(f"Waiting up to 6 minutes on {rat.upper()} RAT reset")
        wait_until_success(360, 5, self.verify_if_rat_is_reseted, node, rat)
        test_logger(f"{rat.upper()} RAT reset completed")

    @staticmethod
    def _generate_delta_scf_from_template(node, delta_plan):
        try:
            nrbts_id_distname = node.admin.get_id_for_current("NRBTS")
            nrbts_id = nrbts_id_distname.rsplit("-", 1)[1] if nrbts_id_distname else ""
        except Exception as e:
            test_logger(str(e), "DEBUG")
            nrbts_id = ""
        scf_params_to_replace = {'MRBTS_ID': node.mrbts_id.replace("MRBTS-", ""),
                                 'NRBTS_ID': nrbts_id}
        if delta_plan.endswith(".json"):
            with open(delta_plan, 'r') as f_delta_template:
                delta_scf = f_delta_template.read()
        else:
            delta_scf = delta_plan

        for k, v in scf_params_to_replace.items():
            delta_scf = delta_scf.replace(f'__{str(k).upper()}__', str(v))
        return delta_scf

    @method_decorator()
    def check_cells_not_affected(self, node):
        wait_until_success(360, 10, self.verify_cells_not_affected, node)

    @method_decorator()
    def verify_cells_not_affected(self, node):
        rat_types = ["nr", "lte", "gsm", "wcdma"]
        rat_types.remove(self.rat_to_reset.lower())
        node.btsverify.set_current_bts_info()
        verification_error = []
        for rat in rat_types:

            cells_status = node.btsverify.cells_verifier.verify_rat_cells_state(rat)
            fault_cells = [entity for entity in cells_status for states in entity.values()
                           if any("Error" in state_value for state_value in states.values())]
            if fault_cells:
                verification_error += fault_cells
        if verification_error:
            raise VerificationBtsFailed(f"Cells with not expected state after Delta Commissiong with "
                                        f"{self.rat_to_reset.upper()} RAT reset")
